~()?\"']/g, ' ')\n .replace(/\\s+/g,:
~()?"']/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Sök- och semantisk sökmotor med hög precision
 */
exportera asynkronfunktion sökSentences(
  query:string,
  filter: SearchFilterOptions = {}
): Promise<{ resultat: SentenceItem[]; total:antal; semanticMatches?: SemanticExplanationMatch[] }> {
  const all = await loadSentences();
  const normalizedQuery = normalizeText(query);
  const queryTokens = normalizedQuery? normalizedQuery.split(' ').filter(Boolean) : [];

  const {
    cefr = 'alla',
    avsnitt = 'alla',
    kategori = 'alla',
    underkategori = 'alla',
    grammatik = 'alla',
    formalitet = 'alla',
    gräns = 50,
    offset = 0,
  } = filter;

  // Filterpass
  låt filtrerad = all.filter(s => {
    if (cefr !== 'alla' && s.cefr !== cefr) returnerar falskt;
    if (sektion !== 'alla' && s.sektion !==sektion) returnerar false;
    if (kategori !== 'alla' && s.category !== kategori) returnerar false;
    if (underkategori !== 'alla' && s.subcategory !== underkategori) returnerar false;
    if (grammar !== 'all' && !s.grammar.toLowerCase().includes(grammar.toLowerCase())) returnerar false;
    if (formality !== 'all' && s.formality.toLowerCase() !== formality.toLowerCase()) returnerar false;
    returnera sant;
  });

  if (!normalizedQuery) {
    const total = filtrerad.längd;
    const paginerad = filtrerad. slice(offset, offset + limit);
    return { resultat: paginerad, totalt };
  }

  // Poängalgoritm
  interfaceScoredItem {
    item:SentenceItem;
    poäng:nummer;
    aspect: SemanticExplanationMatch['matchedAspect'];
  }

  const scored: ScoredItem[] = [];

  för (konst s av filtrerad) {
    let score = 0;
    let matchedAspect: SemanticExplanationMatch['matchedAspect'] = 'engelska';

    const normEn = normaliseraText(s.engelska);
    const normEg = normaliseraText(s.arabicEg);
    const normFusha = normaliseraText(s.arabicFusha);
    const normGrammar = normaliseraText(s.grammar);
    const normPurpose = normaliseraText(s.purpose);

    // Exakt hel meningsmatchning
    if (normEn === normalizedQuery) {
      poäng += 100;
      matchedAspect = 'engelska';
    } else if (normEg === normalizedQuery) {
      poäng += 95;
      matchedAspect = 'arabic-eg';
    } else if (normFusha === normalizedQuery) {
      score += 90;
      matchedAspect = 'arabic-fusha';
    }

    //Substring innehåller
    if (normEn.includes(normalizedQuery)) {
      score += 50;
      matchedAspect = 'engelska';
    } else if (normEg.includes(normalizedQuery)) {
      score += 45;
      matchedAspect = 'arabic-eg';
    } else if (normFusha.includes(normalizedQuery)) {
      score += 40;
      matchedAspect = 'arabic-fusha';
    } else if (normGrammar.includes(normalizedQuery)) {
      score += 35;
      matchedAspect = 'grammatik';
    } else if (normPurpose.includes(normalizedQuery)) {
      score += 30;
      matchedAspect = 'koncept';
    }

    // Token match
    let tokenMatches = 0;
    for (const token of queryTokens) {
      if (normEn.includes(token)) tokenMatcher += 5;
      if (normEg.includes(token)) tokenMatcher += 4;
      if (normFusha.includes(token)) tokenMatches += 3;
      if (s.vocabulary.some(v => normalizeText(v).includes(token))) tokenMatcher += 4;
      if (s.tags.some(t => normaliseraText(t).includes(token))) tokenMatcher += 3;
    }
    score += tokenMatches;

    if (score > 0) {
      scored.push({ objekt: s, poäng, aspekt: matchadAspect });
    }
  }

  scored.sort((a, b) => b.score - a.score);

  // Semantisk förklaring matchar toppartiklar
  const semanticMatches: SemanticExplanationMatch[] = scored.slice(0, 5).map(s => {
    let nuance = '';
    if (s.item.grammar.toLowerCase().includes('past continuous')) {
      nuance = 'Den förflutna tiden visar att en händelse pågick vid en specifik tidpunkt i det förflutna.';
    } else if (s.item.grammar.toLowerCase().includes('present perfect continuous')) {
      nuance = 'Den presens perfekta kontinuerliga tempus betonar tid från det förflutna och fortsätter till ögonblicket av tal.';
    } else if (s.item.grammar.toLowerCase().includes('future perfect')) {
      nuance = 'Den framtida perfekta tiden uttrycker att en händelse kommer att slutföras före en specifik tidpunkt i framtiden.';
    } else if (s.item.grammar.toLowerCase().includes('indirect')) {
      nuance = 'Formen av indirekt begäran är höjdpunkten av diplomatisk etikett i engelsk kommunikation.';
    }
    returnera {
      mening: s.item,
      likhetPoäng: Math.min(100, s.poäng),
      nuanceExplanationAr: nyans,
      matchedAspect: s.aspect,
    };
  });

  konst totalt = poäng. längd;
  const paginerad = scored.slice(offset, offset + limit).map(s => s.item);

  returnera {
    resultat: paginerad,
    totalt,
    semantiska matchningar,
  };
}

/**
 * Deterministisk daglig mening (identisk för alla användare en viss dag)
 */
exportera async-funktion getDailySentence(): Promise<SentenceItem | null> {
  const all = await loadSentences();
  if (all. längd === 0) returnera null;

  const today = new Date();
  const dayOfYear = Math.floor(
    (today.getTime() - new Date(today.getFullYear(), 0, 0).getTime()) / 1000 / 60 / 60 / 24
  );
  const index = Math.abs((dayOfYear * 97 + today.getFullYear()) % all.length);
  returnera alla[index] || alla[0];
}

/**
 * Veckans deterministiska mening
 */
exportera async-funktion getSentenceOfTheWeek(): Promise<SentenceItem | null> {
  const all = await loadSentences();
  if (all. längd === 0) returnera null;

  const today = new Date();
  const weekNumber = Math.ceil(
    ((today.getTime() - new Date(today.getFullYear(), 0, 1). getTime()) / 86400000 + 1) / 7
  );
  // Föredrar B2 eller C1 för veckans mening
  const b2c1 = all.filter(s => s.cefr === 'B2' || s.cefr === 'C1');
  const pool = b2c1.längd > 0 ? b2c1:alla;
  const index = Math.abs((veckaNumber * 31) % pool.length);
  returpool[index] || pool[0];
}

/**
 * Få slumpmässig mening, valfritt CEFR eller avsnittsfilter
 */
exportera async-funktion getRandomSentence(cefr?: CEFRLevel, section?: string): Promise<SentenceItem | null> {
  const all = await loadSentences();
  let pool = all;
  if (cefr) {
    pool = pool.filter(s => s.cefr === cefr);
  }
  if (sektion) {
    pool = pool. filter(s => s. avsnitt === avsnitt);
  }
  if (pool. längd === 0) returnera null;
  const randIdx = Math.floor(Math.random() * pool.length);
  returpool[randIdx];
}
